CREATE OR REPLACE FUNCTION advance_message_trace_revision()
RETURNS trigger AS $$
DECLARE message_id bigint;
BEGIN
  IF TG_TABLE_NAME = 'chat_message_steps' THEN
    message_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.chat_message_id ELSE NEW.chat_message_id END;
  ELSIF TG_TABLE_NAME = 'chat_message_items' THEN
    SELECT chat_message_id INTO message_id FROM chat_message_steps
      WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.chat_message_step_id ELSE NEW.chat_message_step_id END;
  ELSE
    SELECT s.chat_message_id INTO message_id FROM chat_message_items i
      JOIN chat_message_steps s ON s.id = i.chat_message_step_id
      WHERE i.id = CASE WHEN TG_OP = 'DELETE' THEN OLD.chat_message_item_id ELSE NEW.chat_message_item_id END;
  END IF;
  INSERT INTO chat_message_poll_revisions (chat_message_id, revision)
    SELECT id, 1 FROM chat_messages WHERE id = message_id
    ON CONFLICT (chat_message_id) DO UPDATE
      SET revision = chat_message_poll_revisions.revision + 1;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION ic_search_lexemes(body text) RETURNS tsvector LANGUAGE plpgsql IMMUTABLE STRICT AS $$
BEGIN
  -- The built-in text parser treats hosts, emails and paths as compound tokens.
  -- Split ASCII punctuation without treating Unicode combining marks as word breaks.
  body := regexp_replace(normalize(body, NFC) COLLATE "C", '[[:punct:]]+', ' ', 'g');
  -- PostgreSQL limits a single tsvector to 1 MiB. Preserve the source
  -- message even for pathological inputs with huge distinct vocabularies.
  LOOP
    BEGIN
      RETURN to_tsvector('pg_catalog.simple'::regconfig, body);
    EXCEPTION WHEN program_limit_exceeded THEN
      body := left(body, length(body) / 2);
    END;
  END LOOP;
END $$

CREATE FUNCTION ic_refresh_search_after_content_insert() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM ic_refresh_message_search(ARRAY(SELECT DISTINCT s.chat_message_id FROM delta d
  JOIN chat_message_items i ON i.id=d.chat_message_item_id AND i.type IN ('input','handoff_request','handoff_history','handoff_message','answer','handoff_summary')
  JOIN chat_message_steps s ON s.id=i.chat_message_step_id WHERE d.kind='text'
));
  RETURN NULL;
END $$

